#!/usr/bin/env python3
from pathlib import Path

path = Path("smtty")
text = path.read_text(encoding="utf-8")
original = text

helper = '# SMTTY_LAUNCH_OPTIONS_NORMALIZER_BEGIN\nSMTTY_LAUNCH_TOKENS=()\nSMTTY_LAUNCH_NORMALIZE_ERROR=""\nSMTTY_NORMALIZED_ENV=""\nSMTTY_NORMALIZED_COMMAND=""\nSMTTY_NORMALIZED_COUNT=0\n\nsmtty_tokenize_launch_options() {\n  local input=$1\n  local len=${#input}\n  local i=0\n  local ch next quote token\n\n  SMTTY_LAUNCH_TOKENS=()\n  SMTTY_LAUNCH_NORMALIZE_ERROR=""\n\n  while (( i < len )); do\n    while (( i < len )); do\n      ch=${input:i:1}\n      [[ "$ch" =~ [[:space:]] ]] || break\n      i=$((i + 1))\n    done\n    (( i < len )) || break\n\n    token=""\n    quote=""\n\n    while (( i < len )); do\n      ch=${input:i:1}\n\n      if [[ -z "$quote" ]]; then\n        if [[ "$ch" =~ [[:space:]] ]]; then\n          break\n        fi\n        case "$ch" in\n          "\'")\n            quote="\'"\n            token+="$ch"\n            i=$((i + 1))\n            ;;\n          \'"\')\n            quote=\'"\'\n            token+="$ch"\n            i=$((i + 1))\n            ;;\n          \\\\)\n            token+="$ch"\n            i=$((i + 1))\n            if (( i >= len )); then\n              SMTTY_LAUNCH_NORMALIZE_ERROR="Launch options end with an incomplete escape."\n              return 1\n            fi\n            token+="${input:i:1}"\n            i=$((i + 1))\n            ;;\n          \';\'|\'&\'|\'|\'|\'<\'|\'>\'|\'(\'|\')\'|\'`\')\n            SMTTY_LAUNCH_NORMALIZE_ERROR="Unquoted shell control character \'$ch\' is too ambiguous to normalize safely."\n            return 1\n            ;;\n          *)\n            token+="$ch"\n            i=$((i + 1))\n            ;;\n        esac\n      elif [[ "$quote" == "\'" ]]; then\n        token+="$ch"\n        i=$((i + 1))\n        if [[ "$ch" == "\'" ]]; then\n          quote=""\n        fi\n      else\n        token+="$ch"\n        i=$((i + 1))\n        if [[ "$ch" == \'"\' ]]; then\n          quote=""\n        elif [[ "$ch" == \'\\\' ]]; then\n          if (( i >= len )); then\n            SMTTY_LAUNCH_NORMALIZE_ERROR="Launch options end with an incomplete escape."\n            return 1\n          fi\n          next=${input:i:1}\n          token+="$next"\n          i=$((i + 1))\n        fi\n      fi\n    done\n\n    if [[ -n "$quote" ]]; then\n      SMTTY_LAUNCH_NORMALIZE_ERROR="Launch options contain an unterminated quote."\n      return 1\n    fi\n\n    SMTTY_LAUNCH_TOKENS+=("$token")\n  done\n\n  return 0\n}\n\nsmtty_join_launch_tokens() {\n  local -n tokens_ref=$1\n  local joined=""\n  local token\n\n  for token in "${tokens_ref[@]}"; do\n    if [[ -n "$joined" ]]; then\n      joined+=" "\n    fi\n    joined+="$token"\n  done\n\n  printf \'%s\' "$joined"\n}\n\nsmtty_normalize_launch_options() {\n  local input=$1\n  local -a env_tokens=()\n  local -a command_tokens=()\n  local token\n  local i=0\n  local count\n  local command_seen=0\n  local extracted=0\n\n  SMTTY_NORMALIZED_ENV=""\n  SMTTY_NORMALIZED_COMMAND=""\n  SMTTY_NORMALIZED_COUNT=0\n  SMTTY_LAUNCH_NORMALIZE_ERROR=""\n\n  if ! smtty_tokenize_launch_options "$input"; then\n    return 1\n  fi\n\n  count=${#SMTTY_LAUNCH_TOKENS[@]}\n  if (( count == 0 )); then\n    SMTTY_LAUNCH_NORMALIZE_ERROR="Launch options are empty."\n    return 1\n  fi\n\n  while (( i < count )); do\n    token=${SMTTY_LAUNCH_TOKENS[i]}\n\n    if [[ "$token" == "%command%" ]]; then\n      command_seen=1\n      command_tokens+=("$token")\n      i=$((i + 1))\n      continue\n    fi\n\n    if (( command_seen == 0 )); then\n      if [[ "$token" == "gamescope" ]]; then\n        SMTTY_LAUNCH_NORMALIZE_ERROR="The pasted options already contain gamescope. Paste the original game options instead."\n        return 1\n      fi\n\n      if [[ "$token" == "env" ]] && (( i + 1 < count )); then\n        local j=$((i + 1))\n        local env_found=0\n\n        while (( j < count )); do\n          local env_token=${SMTTY_LAUNCH_TOKENS[j]}\n          if [[ "$env_token" =~ ^[A-Za-z_][A-Za-z0-9_]*= ]]; then\n            env_tokens+=("$env_token")\n            env_found=1\n            extracted=$((extracted + 1))\n            j=$((j + 1))\n          else\n            break\n          fi\n        done\n\n        if (( env_found )); then\n          if (( j < count )) && [[ "${SMTTY_LAUNCH_TOKENS[j]}" == "--" ]]; then\n            j=$((j + 1))\n          fi\n          i=$j\n          continue\n        fi\n      fi\n\n      if [[ "$token" =~ ^[A-Za-z_][A-Za-z0-9_]*= ]]; then\n        env_tokens+=("$token")\n        extracted=$((extracted + 1))\n        i=$((i + 1))\n        continue\n      fi\n    fi\n\n    command_tokens+=("$token")\n    i=$((i + 1))\n  done\n\n  if (( command_seen == 0 )); then\n    SMTTY_LAUNCH_NORMALIZE_ERROR="Launch options must contain %command%."\n    return 1\n  fi\n\n  if (( ${#command_tokens[@]} == 0 )); then\n    SMTTY_LAUNCH_NORMALIZE_ERROR="No game command remains after normalization."\n    return 1\n  fi\n\n  SMTTY_NORMALIZED_ENV=$(smtty_join_launch_tokens env_tokens)\n  SMTTY_NORMALIZED_COMMAND=$(smtty_join_launch_tokens command_tokens)\n  SMTTY_NORMALIZED_COUNT=$extracted\n  return 0\n}\n# SMTTY_LAUNCH_OPTIONS_NORMALIZER_END\n'
old_input = '  echo "Enter your current Steam launch options for this game."\n  echo "Example: gamemoderun %command% -novid +fps_max 0 -high -dx12"\n  local CURRENT_LAUNCH_OPTS\n  if ! backable_read CURRENT_LAUNCH_OPTS "Current launch options (empty = just %command%, b = back): "; then\n    echo "Aborting launch options generator."\n    exit 0\n  fi\n\n  if [[ -z "$CURRENT_LAUNCH_OPTS" ]]; then\n    CURRENT_LAUNCH_OPTS=\'%command%\'\n  else\n    if [[ "$CURRENT_LAUNCH_OPTS" != *"%command%"* ]]; then\n      echo "Note: your launch options did not contain %command%; appending at the end."\n      CURRENT_LAUNCH_OPTS="$CURRENT_LAUNCH_OPTS %command%"\n    fi\n  fi\n\n  echo\n'
new_input = '  echo "Enter your current Steam launch options for this game."\n  echo "Example: gamemoderun %command% -novid +fps_max 0 -high -dx12"\n  local CURRENT_LAUNCH_OPTS\n  local NORMALIZED_LAUNCH_ENV=""\n\n  while :; do\n    if ! backable_read CURRENT_LAUNCH_OPTS "Current launch options (empty = just %command%, b = back): "; then\n      echo "Aborting launch options generator."\n      exit 0\n    fi\n\n    if [[ -z "$CURRENT_LAUNCH_OPTS" ]]; then\n      CURRENT_LAUNCH_OPTS=\'%command%\'\n    elif [[ "$CURRENT_LAUNCH_OPTS" != *"%command%"* ]]; then\n      echo "Note: your launch options did not contain %command%; appending at the end."\n      CURRENT_LAUNCH_OPTS="$CURRENT_LAUNCH_OPTS %command%"\n    fi\n\n    if smtty_normalize_launch_options "$CURRENT_LAUNCH_OPTS"; then\n      NORMALIZED_LAUNCH_ENV="$SMTTY_NORMALIZED_ENV"\n      CURRENT_LAUNCH_OPTS="$SMTTY_NORMALIZED_COMMAND"\n      if (( SMTTY_NORMALIZED_COUNT > 0 )); then\n        echo "Moved $SMTTY_NORMALIZED_COUNT environment assignment(s) before gamescope:"\n        echo "  $NORMALIZED_LAUNCH_ENV"\n      fi\n      break\n    fi\n\n    print_error "$SMTTY_LAUNCH_NORMALIZE_ERROR"\n    echo "Re-enter the original launch options so smtty does not generate a broken command."\n    echo\n  done\n\n  echo\n'
old_output = '  printf \'%s\' "$env_prefix"\n  if (( use_flatpak_prefix )); then\n    printf \'flatpak-spawn --host \'\n  fi\n  printf \'gamescope\'\n  if (( use_steam_integration )); then\n    printf \' -e\'\n  fi\n  printf \' %q\' "${args[@]}"\n  printf \' -- %s\\n\' "$CURRENT_LAUNCH_OPTS"\n'
new_output = '  printf \'%s\' "$env_prefix"\n  if [[ -n "$NORMALIZED_LAUNCH_ENV" ]]; then\n    printf \'%s \' "$NORMALIZED_LAUNCH_ENV"\n  fi\n  if (( use_flatpak_prefix )); then\n    printf \'flatpak-spawn --host \'\n  fi\n  printf \'gamescope\'\n  if (( use_steam_integration )); then\n    printf \' -e\'\n  fi\n  printf \' %q\' "${args[@]}"\n  printf \' -- %s\\n\' "$CURRENT_LAUNCH_OPTS"\n'

if "# SMTTY_LAUNCH_OPTIONS_NORMALIZER_BEGIN" not in text:
    anchor = "\nprint_steam_launch_options() {"
    if text.count(anchor) != 1:
        raise SystemExit("expected one print_steam_launch_options anchor")
    text = text.replace(anchor, "\n" + helper.rstrip() + "\n\nprint_steam_launch_options() {", 1)

if old_input in text:
    text = text.replace(old_input, new_input, 1)
elif 'local NORMALIZED_LAUNCH_ENV=""' not in text:
    raise SystemExit("launch-option input block did not match and is not already patched")

if old_output in text:
    text = text.replace(old_output, new_output, 1)
elif 'printf \'%s \' "$NORMALIZED_LAUNCH_ENV"' not in text:
    raise SystemExit("launch-option output block did not match and is not already patched")

if text != original:
    path.write_text(text, encoding="utf-8")
    print("patched smtty launch-option generator")
else:
    print("smtty launch-option generator already patched")
